import { useEffect, useState } from 'react'
import { api } from './api'
import { AgentTiles } from './components/AgentTiles'
import { BeforeAfterViewer } from './components/BeforeAfterViewer'
import { ChecksTable } from './components/ChecksTable'
import { ClaimsList } from './components/ClaimsList'
import { CompanyCard } from './components/CompanyCard'
import { ComplianceCard } from './components/ComplianceCard'
import { JobBar } from './components/JobBar'
import { ModelViewer } from './components/ModelViewer'
import { Onboarding } from './components/Onboarding'
import { ProjectCard } from './components/ProjectCard'
import type { ProjectId } from './projects'
import { Recommendations } from './components/Recommendations'
import { RiskTable } from './components/RiskTable'
import { useJob, type CreateJobOptions } from './job'
import { askLiveToken } from './liveToken'
import {
  loadSaved,
  matchesDemo,
  needsLiveAgents,
  saveOnboarded,
  toRobot,
  type Onboarded,
} from './onboarding/answers'
import type { OpenAnswers } from './onboarding/questions'
import type { ComplianceCard as Card, Robot } from './types'

// ?live=1 shows a "Run live" button. The token is asked once per tab and kept in sessionStorage.
const params = new URLSearchParams(window.location.search)
const LIVE_ENABLED = params.get('live') === '1'

/** Start a job that makes real calls ('mixed' replays what is recorded and runs the rest). */
function startWithToken(
  mode: 'live' | 'mixed',
  start: (mode: 'live' | 'mixed', opts: CreateJobOptions) => void,
  opts: CreateJobOptions,
) {
  const token = askLiveToken('Live jobs spend TinyFish credit. Enter the live token:')
  if (token) start(mode, { ...opts, liveToken: token })
}

/** What the robot panel shows before a job: the CAD worker's starter design for the project. */
function starterRobot(project: ProjectId) {
  if (project === 'ar4_club')
    return { src: '/cad/designs/starter_ar4/glb', title: 'Robot: AR4 arm, NEMA 23 J2 motor' }
  if (project === 'stretch')
    return { src: '/cad/designs/starter_stretch/glb', title: 'Robot: Stretch, NEMA 34 shoulder motor' }
  return { src: '/cad/designs/starter/glb', title: 'Robot: NEMA 23 stepper baseline' }
}

export default function App() {
  const [health, setHealth] = useState<string>('checking…')
  const [baselineCard, setBaselineCard] = useState<Card | null>(null)
  const { state: job, start } = useJob()
  const [project, setProject] = useState<ProjectId>('')
  const projectId = project || undefined
  // Onboarding: the demo robot gives the defaults; `saved` is what the user confirmed before
  // (onboarded: null = they skipped to the demo robot).
  const [demo, setDemo] = useState<Robot | null>(null)
  const [example, setExample] = useState<OpenAnswers | null>(null)
  const [saved, setSaved] = useState(loadSaved)
  const [view, setView] = useState<'onboarding' | 'dashboard'>(saved ? 'dashboard' : 'onboarding')
  const onboarded = saved?.onboarded ?? null

  useEffect(() => {
    api.health().then((h) => setHealth(h.status), () => setHealth('backend unreachable'))
    api.robot().then(setDemo, console.error)
    api.example().then(setExample, console.error)
    api.compliance().then(setBaselineCard, console.error)
  }, [])

  const jobOptions = (o: Onboarded | null): CreateJobOptions => ({
    projectId,
    robot: o && demo && !projectId ? toRobot(o, demo) : undefined,
    company: o && demo && !projectId ? o.company : undefined,
  })
  /** Replay when the recordings fit this robot; otherwise a mixed job, which needs the token. */
  const run = (o: Onboarded | null) => {
    if (o && !projectId && needsLiveAgents(o.specs)) startWithToken('mixed', start, jobOptions(o))
    else start('replay', jobOptions(o))
  }
  const finishOnboarding = (o: Onboarded | null) => {
    saveOnboarded(o)
    setSaved({ onboarded: o })
    setView('dashboard')
    if (o) run(o)
  }

  if (view === 'onboarding') {
    return (
      <main className="ob-page">
        {demo ? (
          <Onboarding
            demo={demo}
            example={example}
            initial={onboarded}
            onDone={finishOnboarding}
            onSkip={() => finishOnboarding(null)}
          />
        ) : (
          <p className="muted">
            {health === 'backend unreachable' ? 'The backend is unreachable, so the questions cannot load.' : 'Loading…'}
          </p>
        )}
      </main>
    )
  }

  const runs = job.runOrder.map((id) => job.runs[id])
  // The baseline compliance card comes from an endpoint that always uses the demo robot, so it
  // is only right when the user's robot gives the same numbers.
  const demoPanels = !onboarded || (demo != null && matchesDemo(onboarded, demo))
  const card = job.compliance ?? (demoPanels ? baselineCard : null)

  return (
    <main>
      <header>
        <h1>AI Robot Redesign Engine</h1>
        <span className="muted">
          API: {health} ·{' '}
          <button type="button" className="ob-link" onClick={() => setView('onboarding')}>
            {onboarded ? 'Edit answers' : 'Describe your robot'}
          </button>
        </span>
      </header>
      <JobBar
        state={job}
        onStart={() => run(onboarded)}
        onStartLive={LIVE_ENABLED ? () => startWithToken('live', start, jobOptions(onboarded)) : undefined}
        project={project}
        onProjectChange={setProject}
      />
      {onboarded && !job.project && <CompanyCard company={onboarded.company} />}
      {job.project && <ProjectCard project={job.project} criteria={job.criteria} claims={job.claims} />}
      {job.riskLines.length > 0 && <RiskTable rows={job.riskLines} alternatives={job.alternatives} />}
      {job.recommendations.length > 0 && (
        <Recommendations
          recommendations={job.recommendations}
          rows={job.riskLines}
          alternatives={job.alternatives}
        />
      )}
      {job.baseline && job.candidates[0] ? (
        <BeforeAfterViewer before={job.baseline} after={job.candidates[0]} />
      ) : (
        <ModelViewer {...starterRobot(project)} />
      )}
      <div className="grid">
        {(card || demoPanels) && <ComplianceCard card={card} />}
        <AgentTiles runs={runs} />
      </div>
      <ClaimsList claims={job.claims} />
      {job.jobId && <ChecksTable checks={job.checks} candidates={job.candidates} />}
      <footer className="muted">
        Not legal advice. Pass* = passes the checks we implemented, not engineering certification.
      </footer>
    </main>
  )
}
import { useEffect, useState } from 'react'
import { askLiveToken, forgetLiveToken, storedLiveToken } from '../liveToken'
import {
  applyDrafts,
  needsLiveAgents,
  stillMissing,
  withDefaults,
  type Onboarded,
} from '../onboarding/answers'
import {
  ApiError,
  intake,
  type CadMeasure,
  type CompanyFact,
  type IntakeResult,
  type SpecRow,
} from '../onboarding/intake'
import { EMPTY_ANSWERS, QUESTIONS, listOf, type OpenAnswers } from '../onboarding/questions'
import type { BomRow, Robot } from '../types'
import { BomUpload } from './BomUpload'
import { CadUpload } from './CadUpload'
import { SpecsReview } from './SpecsReview'

interface Props {
  demo: Robot
  /** The recorded example answers (data/onboarding_example.json); null while loading. */
  example: OpenAnswers | null
  /** Set when the user comes back to edit: opens on the review screen. */
  initial: Onboarded | null
  onDone: (onboarded: Onboarded) => void
  /** Leave onboarding without answers and use the demo robot. */
  onSkip: () => void
}

// who, market, limits, then files, then the drivetrain question, then review.
const STEPS = ['who', 'market', 'limits', 'files', 'drivetrain', 'review'] as const
const REVIEW = STEPS.indexOf('review')
const TOKEN_MESSAGE = 'Reading new answers makes a real Gemini call. Enter the live token:'

/** Typeform-style intake: one open question on screen, files in the middle, then every number
 * the job will use for the user to confirm. */
export function Onboarding({ demo, example, initial, onDone, onSkip }: Props) {
  const [answers, setAnswers] = useState<OpenAnswers>(initial?.answers ?? EMPTY_ANSWERS)
  const [bom, setBom] = useState<BomRow[]>(initial?.bom ?? [])
  const [cad, setCad] = useState<CadMeasure | null>(null)
  // What the files alone gave us (decides what the drivetrain question asks for).
  const [fromFiles, setFromFiles] = useState<SpecRow[] | null>(null)
  // The full reading, the inputs it was made from, and the user's edits on top of it.
  const [specs, setSpecs] = useState<SpecRow[]>(initial?.specs ?? [])
  const [company, setCompany] = useState<CompanyFact[]>(initial?.company ?? [])
  const [dropped, setDropped] = useState<string[]>([])
  const [drafts, setDrafts] = useState<Record<string, string>>({})
  const inputsKey = (a: OpenAnswers, b: BomRow[], c: CadMeasure | null) => JSON.stringify([a, b, c])
  const [readKey, setReadKey] = useState(initial ? inputsKey(initial.answers, initial.bom, null) : '')

  const [index, setIndex] = useState(initial ? REVIEW : 0)
  const [back, setBack] = useState(false)
  const [busy, setBusy] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const step = STEPS[index]
  const question = QUESTIONS.find((q) => q.id === step)
  const go = (to: number) => {
    setBack(to < index)
    setIndex(to)
    setError(null)
  }

  /** One Gemini reading of the answers. Asks for the live token only when the backend wants it. */
  const read = async (): Promise<IntakeResult | null> => {
    const input = { bom, cad, answers }
    try {
      return await intake(input, storedLiveToken())
    } catch (e) {
      if (!(e instanceof ApiError) || e.status !== 403) throw e
    }
    forgetLiveToken()
    const token = askLiveToken(TOKEN_MESSAGE)
    if (!token) return null
    try {
      return await intake(input, token)
    } catch (e) {
      if (e instanceof ApiError && e.status === 403) forgetLiveToken()
      throw e
    }
  }

  const work = async (label: string, job: () => Promise<void>) => {
    setBusy(label)
    setError(null)
    try {
      await job()
    } catch (e) {
      setError(e instanceof ApiError ? e.message : String(e))
    } finally {
      setBusy(null)
    }
  }

  const finish = () => {
    const applied = applyDrafts(specs, drafts)
    if (!applied.ok) return setError(applied.error)
    const cleaned = company.map((c) => ({ ...c, value: c.value.trim() })).filter((c) => c.value)
    const country = cleaned.find((c) => c.field === 'final_assembly_country')
    if (!country || !/^[A-Za-z]{2}$/.test(country.value)) {
      return setError('Final assembly needs a 2-letter country code, like US or CA.')
    }
    onDone({ answers, bom, company: cleaned, specs: applied.specs })
  }

  /** Check the current step and move on. */
  const next = () => {
    if (busy) return
    if (step === 'review') return finish()
    if (step === 'files') {
      if (bom.length === 0) return setError('Upload a BOM CSV, or use the sample BOM.')
      return void work('Reading your files…', async () => {
        setFromFiles((await intake({ bom, cad, answers: null })).specs)
        go(index + 1)
      })
    }
    if (step === 'drivetrain') {
      if (readKey === inputsKey(answers, bom, cad)) return go(REVIEW) // nothing changed: keep edits
      return void work('Reading your answers…', async () => {
        const result = await read()
        if (!result) return setError('Reading new answers needs the live token.')
        setSpecs(result.specs)
        setCompany(withDefaults(result.company, demo))
        setDropped(result.dropped)
        setDrafts({})
        setReadKey(inputsKey(answers, bom, cad))
        go(REVIEW)
      })
    }
    if (question?.required && !answers[question.id].trim()) return setError('Please type an answer.')
    go(index + 1)
  }

  const fillExample = () => {
    if (!example) return
    setAnswers(example)
    setBom(demo.bom)
    setError(null)
  }

  // Enter goes on (Shift+Enter is a new line in an answer). Re-bound every render so the handler
  // always sees the current step.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Enter' || e.shiftKey) return
      const el = e.target as HTMLElement
      const text = el.tagName === 'TEXTAREA' || (el.tagName === 'INPUT' && (el as HTMLInputElement).type !== 'file')
      // Buttons, links, <summary> and the file picker act on Enter themselves.
      if (!text && ['BUTTON', 'A', 'SUMMARY', 'INPUT'].includes(el.tagName)) return
      e.preventDefault()
      next()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  })

  const missing = fromFiles ? stillMissing(fromFiles) : []
  const found = (fromFiles ?? []).filter((s) => s.source === 'bom' || s.source === 'cad')
  const applied = applyDrafts(specs, drafts)
  const live = needsLiveAgents(applied.ok ? applied.specs : specs)

  return (
    <div className="ob">
      <div
        className="ob-progress"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={REVIEW}
        aria-valuenow={index}
        aria-label="Onboarding progress"
      >
        <div style={{ width: `${(index / REVIEW) * 100}%` }} />
      </div>

      <div className={`ob-step${back ? ' back' : ''}`} key={index}>
        <p className="ob-count muted">
          {step === 'review' ? 'Review' : `Step ${index + 1} of ${REVIEW}`}
        </p>

        {question && (
          <>
            <h1 className="ob-prompt">{question.prompt}</h1>
            <p className="ob-help muted">
              {step === 'drivetrain' && missing.length > 0
                ? `We still need ${listOf(missing)}. Anything you leave out keeps a default you can change on the next screen.`
                : question.help}
            </p>
            {step === 'drivetrain' && found.length > 0 && (
              <p className="ob-help muted">
                From your files:{' '}
                {listOf(
                  found.map(
                    (s) =>
                      `${s.label.toLowerCase()} ${s.value}${s.unit ? ` ${s.unit}` : ''}` +
                      (s.evidence?.startsWith('estimate') ? ' (an estimate)' : ''),
                  ),
                )}
                .
              </p>
            )}
            <textarea
              className="ob-input ob-text"
              autoFocus
              rows={4}
              value={answers[question.id]}
              placeholder="Type your answer here…"
              aria-label={question.prompt}
              aria-invalid={error != null}
              onChange={(e) => {
                setAnswers({ ...answers, [question.id]: e.target.value })
                setError(null)
              }}
            />
          </>
        )}

        {step === 'files' && (
          <>
            <h1 className="ob-prompt">Upload your bill of materials.</h1>
            <p className="ob-help muted">
              A CSV with one part per line: part, category, qty, unit_cost_usd, origin. We read what we can from
              it before asking anything else.
            </p>
            <BomUpload
              rows={bom}
              sample={demo.bom}
              onChange={(rows) => {
                setBom(rows)
                setError(null)
              }}
            />
            <CadUpload cad={cad} onChange={setCad} />
          </>
        )}

        {step === 'review' && (
          <>
            <h1 className="ob-prompt">Does this look right?</h1>
            <p className="ob-help muted">
              These are the numbers the job will use. Change any of them; each one shows where it came from.
            </p>
            <SpecsReview
              rows={specs}
              drafts={drafts}
              onDraft={(field, text) => {
                setDrafts({ ...drafts, [field]: text })
                setError(null)
              }}
            />
            <div className="ob-specs">
              <table>
                <caption>About you</caption>
                <tbody>
                  {company.map((c) => (
                    <tr key={c.field}>
                      <th scope="row">
                        <label htmlFor={`fact-${c.field}`}>{c.label}</label>
                        {c.quote && <span className="muted ob-evidence">“{c.quote}”</span>}
                      </th>
                      <td className="ob-spec-value">
                        <input
                          id={`fact-${c.field}`}
                          className="ob-input wide"
                          value={c.value}
                          onChange={(e) => {
                            setCompany(company.map((x) => (x.field === c.field ? { ...x, value: e.target.value } : x)))
                            setError(null)
                          }}
                        />
                      </td>
                      <td>
                        <span className={`badge source-${c.quote ? 'answer' : 'default'}`}>
                          {c.quote ? 'from your answer' : 'default'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {dropped.length > 0 && (
              <details className="ob-advanced">
                <summary>{dropped.length} things we read but could not confirm</summary>
                <ul>
                  {dropped.map((d) => (
                    <li key={d}>{d}</li>
                  ))}
                </ul>
              </details>
            )}
            {live && (
              <p className="ob-live">
                Your drivetrain differs from the recorded demo, so agents will run live (up to 8 TinyFish agent
                runs, needs the live token).
              </p>
            )}
          </>
        )}

        {error && (
          <p className="error" role="alert">
            {error}
          </p>
        )}

        <div className="ob-nav">
          <button type="button" className="primary" onClick={next} disabled={busy != null}>
            {busy ?? (step === 'review' ? 'Find and Redesign' : 'OK')}
          </button>
          {!busy && (
            <span className="muted ob-hint">
              press <kbd>Enter</kbd>
            </span>
          )}
          {index > 0 && (
            <button type="button" className="secondary" onClick={() => go(index - 1)} disabled={busy != null}>
              Back
            </button>
          )}
          {index === 0 && (
            <>
              {example && (
                <button type="button" className="ob-link" onClick={fillExample}>
                  Use the example
                </button>
              )}
              <button type="button" className="ob-link" onClick={onSkip}>
                Skip to the demo robot
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

// The four open questions. Answers are free text: the backend reads them with Gemini and code
// confirms every value against the user's own words (backend/app/intake/extract.py).

export type QuestionId = 'who' | 'market' | 'limits' | 'drivetrain'
export type OpenAnswers = Record<QuestionId, string>

export interface Question {
  id: QuestionId
  prompt: string
  help: string
  required?: boolean
}

export const QUESTIONS: Question[] = [
  {
    id: 'who',
    prompt: 'Who are you, and what are you building?',
    help: 'Your company or team, the robot and what it does.',
    required: true,
  },
  {
    id: 'market',
    prompt: 'Who buys it, where is it assembled and where will it run?',
    help: 'Customers (any government buyers?), final assembly country, countries it is deployed in, and how much downtime hurts.',
  },
  {
    id: 'limits',
    prompt: 'What limits matter: budget, deadline, anything to avoid?',
    help: 'Parts budget per robot, when you need parts, and suppliers, countries or materials you want to stay away from.',
  },
  {
    id: 'drivetrain',
    prompt: 'What else should we know about the drivetrain?',
    help: 'Plain words and any units are fine.',
  },
]

export const EMPTY_ANSWERS: OpenAnswers = { who: '', market: '', limits: '', drivetrain: '' }

/** "a", "a and b", "a, b and c". */
export function listOf(items: string[]): string {
  if (items.length <= 1) return items.join('')
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`
}

interface Props {
  state: JobState
  onStart: () => void
  /** Shown only with ?live=1 in the URL: starts a real (credit-spending) TinyFish job. */
  onStartLive?: () => void
  project: ProjectId
  /** Omit to hide the project switcher. */
  onProjectChange?: (id: ProjectId) => void
}

export function JobBar({ state, onStart, onStartLive, project, onProjectChange }: Props) {
  const running = state.connection === 'starting' || state.connection === 'streaming'
  const current = state.stage ? STAGE_ORDER.indexOf(state.stage) : -1
  const failed = state.stage === 'FAILED' || state.stage === 'DEGRADED'

  return (
    <section className="panel jobbar">
      <div className="jobbar-row">
        {onProjectChange && (
          <ProjectSwitcher value={project} onChange={onProjectChange} disabled={running} />
        )}
        <button className="primary" onClick={onStart} disabled={running}>
          {running ? 'Running…' : state.jobId ? 'Run again' : 'Find and Redesign'}
        </button>
        {onStartLive && (
          <button className="secondary" onClick={onStartLive} disabled={running}>
            Run live
          </button>
        )}
        {state.mode && (
          <span className={`badge badge-${state.mode}`}>{state.mode.toUpperCase()}</span>
        )}
        {state.jobId && <span className="muted">job {state.jobId}</span>}
        {failed && <span className="badge badge-bad">{state.stage}</span>}
      </div>
      {state.jobId && (
        <ol className="stepper">
          {STAGE_ORDER.map((stage, i) => (
            <li
              key={stage}
              className={i < current ? 'done' : i === current ? 'current' : ''}
              title={stage}
            >
              {stage.replace('_', ' ').toLowerCase()}
            </li>
          ))}
        </ol>
      )}
      {state.errors.map((e) => (
        <p key={e} className="error">
          {e}
        </p>
      ))}
    </section>
  )
}

const OUTCOME: Record<Outcome, { icon: string; label: string }> = {
  success: { icon: '✅', label: 'verified source' },
  blocked: { icon: '⚠️', label: 'blocked' },
  auth_required: { icon: '⚠️', label: 'needs login' },
  incomplete: { icon: '⚠️', label: 'incomplete' },
  not_found: { icon: '❌', label: 'not found' },
  error: { icon: '❌', label: 'error' },
}

function Tile({ run }: { run: Run }) {
  const showStream = run.live && run.streamingUrl && run.outcome === null
  const outcome = run.outcome ? OUTCOME[run.outcome] : null
  return (
    <article className="tile">
      <header className="tile-head">
        <span className={`badge ${run.live ? 'badge-live' : 'badge-replay'}`}>
          {run.live ? 'LIVE' : 'REPLAY'}
        </span>
        <strong>{run.site}</strong>
        <span className="muted">{run.worker}</span>
      </header>
      {showStream ? (
        <iframe
          className="tile-stream"
          src={run.streamingUrl ?? undefined}
          title={`Agent browser for ${run.site}`}
          referrerPolicy="no-referrer"
        />
      ) : (
        <ol className="tile-steps">
          {run.steps.length === 0 ? <li className="muted">starting…</li> : null}
          {run.steps.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ol>
      )}
      <footer className="tile-foot">
        {outcome ? (
          <span title={run.reason ?? ''}>
            {outcome.icon} {outcome.label}
            {run.reason ? <span className="muted"> · {run.reason}</span> : null}
          </span>
        ) : (
          <span className="muted">running…</span>
        )}
        {run.url && (
          <a href={run.url} target="_blank" rel="noreferrer">
            page
          </a>
        )}
      </footer>
    </article>
  )
}

export function AgentTiles({ runs }: { runs: Run[] }) {
  return (
    <section className="panel">
      <h2>Agent swarm</h2>
      {runs.length === 0 ? (
        <p className="muted">Click Find and Redesign to send the agents out.</p>
      ) : (
        <div className="tiles">
          {runs.map((r) => (
            <Tile key={r.runId} run={r} />
          ))}
        </div>
      )}
    </section>
  )
}

const money = (v: number | null) => (v === null ? '–' : `$${v.toLocaleString()}`)

export function LevelChip({ level, title, children }: { level: Level; title?: string; children?: string }) {
  return (
    <span className={`chip level-${level}`} title={title}>
      {children ?? level}
    </span>
  )
}

function Alternatives({ alts }: { alts: Alternative[] }) {
  return (
    <details>
      <summary>
        {alts.length} alternative{alts.length === 1 ? '' : 's'}
      </summary>
      <table className="nested">
        <thead>
          <tr>
            <th>Part</th>
            <th>Origin</th>
            <th>Price</th>
            <th>Availability</th>
            <th>Checks</th>
            <th>Risk</th>
          </tr>
        </thead>
        <tbody>
          {alts.map((a) => (
            <tr key={a.id}>
              <td>
                {a.manufacturer} {a.part_number}{' '}
                {a.live && <span className="badge badge-live">LIVE FIND</span>}
              </td>
              <td>
                {a.origin_country ?? '?'} {a.origin_tier && <span className="muted">{a.origin_tier}</span>}
              </td>
              <td>{money(a.unit_price_usd)}</td>
              <td>
                {a.availability.replace('_', ' ')}
                {a.lead_time_days != null && ` (${a.lead_time_days} d)`}
              </td>
              <td>{a.verdict ?? <span className="muted">–</span>}</td>
              <td>
                <LevelChip level={a.risk.overall} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </details>
