/** One row per BOM line: five risk factors, the overall level (= worst known factor) and the
 * alternatives found for it. */
export function RiskTable({ rows, alternatives }: { rows: RiskRow[]; alternatives: Record<string, Alternative[]> }) {
  return (
    <section className="panel">
      <h2>Supply risk by part</h2>
      <table>
        <thead>
          <tr>
            <th>Part</th>
            <th>Domain</th>
            <th>Qty</th>
            <th>Risk factors</th>
            <th>Overall</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(({ line, risk }) => {
            const alts = alternatives[line.id] ?? []
            return (
              <Fragment key={line.id}>
                <tr>
                  <td>
                    {line.part}
                    {line.manufacturer && <span className="muted"> · {line.manufacturer}</span>}{' '}
                    {line.illustrative && (
                      <span className="badge badge-illustrative" title="real part of the right class, not the company's actual BOM">
                        ILLUSTRATIVE
                      </span>
                    )}
                    {line.sources.length > 0 && (
                      <span className="muted">
                        {' '}
                        {line.sources.map((url, i) => (
                          <a key={url} href={url} target="_blank" rel="noreferrer" title={url}>
                            [{i + 1}]
                          </a>
                        ))}
                      </span>
                    )}
                  </td>
                  <td>{line.domain}</td>
                  <td>{line.qty}</td>
                  <td className="chips">
                    {RISK_FACTORS.map((name) => {
                      const f = risk.factors.find((x) => x.name === name)
                      return (
                        <LevelChip
                          key={name}
                          level={f?.level ?? 'unknown'}
                          title={f ? [`${f.value} · ${f.reason}`, ...f.source_urls].join('\n') : 'not assessed'}
                        >
                          {name}
                        </LevelChip>
                      )
                    })}
                  </td>
                  <td>
                    <LevelChip level={risk.overall} />
                  </td>
                </tr>
                {alts.length > 0 && (
                  <tr className="subrow">
                    <td colSpan={5}>
                      <Alternatives alts={alts} />
                    </td>
                  </tr>
                )}
              </Fragment>
            )
          })}
        </tbody>
      </table>
    </section>
  )
}

const ACTION: Record<Recommendation['action'], string> = {
  keep: 'Keep',
  dual_source: 'Dual-source',
  re_source: 'Re-source',
}

const delta = (v: number | null) =>
  v === null ? '–' : `${v > 0 ? '+' : v < 0 ? '−' : ''}$${Math.abs(v).toLocaleString()}`

/** The team's decision per part, already ranked by the backend's rule (most risk removed first,
 * then cheapest). */
export function Recommendations({
  recommendations,
  rows,
  alternatives,
}: {
  recommendations: Recommendation[]
  rows: RiskRow[]
  alternatives: Record<string, Alternative[]>
}) {
  const part = (lineId: string) => rows.find((r) => r.line.id === lineId)?.line.part ?? lineId
  const alt = (r: Recommendation) =>
    r.alternative_id ? alternatives[r.line_id]?.find((a) => a.id === r.alternative_id) : undefined

  return (
    <section className="panel">
      <h2>Recommendations</h2>
      <table>
        <thead>
          <tr>
            <th>#</th>
            <th>Part</th>
            <th>Action</th>
            <th>With</th>
            <th>Cost Δ</th>
            <th>Risk</th>
            <th>Why</th>
          </tr>
        </thead>
        <tbody>
          {recommendations.map((r, i) => {
            const a = alt(r)
            return (
              <tr key={r.line_id}>
                <td>{i + 1}</td>
                <td>{part(r.line_id)}</td>
                <td>
                  <span className={`action action-${r.action}`}>{ACTION[r.action]}</span>
                </td>
                <td>{a ? `${a.manufacturer} ${a.part_number}` : (r.alternative_id ?? '–')}</td>
                <td>{delta(r.cost_delta_usd)}</td>
                <td className="chips">
                  <LevelChip level={r.risk_before} /> → <LevelChip level={r.risk_after} />
                </td>
                <td>{r.reason}</td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </section>
  )
}

